-- Recovered from production schema_migrations (applied there outside this repo).
create unique index automation_hub_one_pending_command on public.automation_hub_commands(task_id) where state in ('pending','processing'); alter table public.automation_hub_commands add constraint automation_hub_action_payload_required check (coalesce((action='set_enabled' and jsonb_typeof(payload->'enabled')='boolean') or (action='update_prompt' and jsonb_typeof(payload->'prompt')='string' and length(payload->>'prompt') between 10 and 16000) or (action='update_schedule' and jsonb_typeof(payload->'hours')='number' and (payload->>'hours')::numeric in (1,2,4,6,12,24)) or (action='update_schedule' and jsonb_typeof(payload->'time')='string' and (payload->>'time') ~ '^([01][0-9]|2[0-3]):[0-5][0-9]$'),false));
